import os, base64
files = {
    'detect.py': '',
    'decider.py': '',
    'llm.py': '',
}

targets = {
    "detect.py":  "testbot/uied/detect.py",
    "decider.py": "testbot/roles/decider.py",
    "llm.py":     "testbot/llm.py",
}
for name, target in targets.items():
    content = base64.b64decode(files[name])
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, "wb") as f:
        f.write(content)
    print(f"Written: {target}")
print("All files updated.")
